code.cpp:
long long totalOperations(int n) {
    long long ops = 0;
    int cap = 1, size = 0;
    for (int i = 0; i < n; i++) {
        if (size == cap) {
            ops += size;  // copy cost
            cap *= 2;
        }
        ops += 1;  // insert cost
        size++;
    }
    return ops;
}

