code.cpp:
#include<iostream>
#include<cmath>
using namespace std;
int main() {
    long long T;
    cin >> T;
    // O(n)
    long long r1 = T;
    // O(n log n) - binary search
    long long lo = 1, hi = T, r2 = 1;
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        double val = mid * (log2((double)mid));
        if (mid == 1 || val <= T) { r2 = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    // O(n^2)
    long long r3 = (long long)sqrt((double)T);
    while ((r3+1)*(r3+1) <= T) r3++;
    // O(n^3)
    long long r4 = (long long)cbrt((double)T);
    while ((r4+1)*(r4+1)*(r4+1) <= T) r4++;
    // O(2^n)
    int r5 = 0;
    long long pw = 1;
    while (pw <= T && r5 < 25) { r5++; if (pw > T/2) break; pw *= 2; }
    if (pw > T) r5--;
    if (r5 < 1) r5 = 1;
    // O(n!)
    int r6 = 1;
    long long fact = 1;
    while (r6 < 25) {
        if (fact > T / (r6 + 1)) break;
        fact *= (r6 + 1);
        if (fact > T) break;
        r6++;
    }
    cout << r1 << " " << r2 << " " << r3 << " " << r4 << " " << r5 << " " << r6;
}
